    if effectPath == nil then
        effectPath = "Abilities\\Spells\\Human\\Thunderclap\\ThunderclapTarget.mdx"
    end
    EXPauseUnit(unitHandle, true)
    local effect = AddSpecialEffectTarget(effectPath, unitHandle, "head")
